const data = JSON.stringify({
  "email": "foo@bar.foo",
  "password": "secretFooBar"
});

const xhr = new XMLHttpRequest();
xhr.withCredentials = true;

xhr.addEventListener("readystatechange", function () {
  if (this.readyState === this.DONE) {
    console.log(this.responseText);
  }
});

xhr.open("POST", "https://metrics-api.nanostream.cloud/authenticate");
xhr.setRequestHeader("content-type", "application/json");

xhr.send(data);

const unirest = require("unirest");

const req = unirest("POST", "https://metrics-api.nanostream.cloud/authenticate");

req.headers({
  "content-type": "application/json"
});

req.type("json");
req.send({
  "email": "foo@bar.foo",
  "password": "secretFooBar"
});

req.end(function (res) {
  if (res.error) throw new Error(res.error);

  console.log(res.body);
});

import requests

url = "https://metrics-api.nanostream.cloud/authenticate"

payload = {
    "email": "foo@bar.foo",
    "password": "secretFooBar"
}
headers = {"content-type": "application/json"}

response = requests.request("POST", url, json=payload, headers=headers)

print(response.text)

import Foundation

let headers = ["content-type": "application/json"]
let parameters = [
  "email": "foo@bar.foo",
  "password": "secretFooBar"
] as [String : Any]

let postData = JSONSerialization.data(withJSONObject: parameters, options: [])

let request = NSMutableURLRequest(url: NSURL(string: "https://metrics-api.nanostream.cloud/authenticate")! as URL,
                                        cachePolicy: .useProtocolCachePolicy,
                                    timeoutInterval: 10.0)
request.httpMethod = "POST"
request.allHTTPHeaderFields = headers
request.httpBody = postData as Data

let session = URLSession.shared
let dataTask = session.dataTask(with: request as URLRequest, completionHandler: { (data, response, error) -> Void in
  if (error != nil) {
    print(error)
  } else {
    let httpResponse = response as? HTTPURLResponse
    print(httpResponse)
  }
})

dataTask.resume()

CURL *hnd = curl_easy_init();

curl_easy_setopt(hnd, CURLOPT_CUSTOMREQUEST, "POST");
curl_easy_setopt(hnd, CURLOPT_URL, "https://metrics-api.nanostream.cloud/authenticate");

struct curl_slist *headers = NULL;
headers = curl_slist_append(headers, "content-type: application/json");
curl_easy_setopt(hnd, CURLOPT_HTTPHEADER, headers);

curl_easy_setopt(hnd, CURLOPT_POSTFIELDS, "{\"email\":\"foo@bar.foo\",\"password\":\"secretFooBar\"}");

CURLcode ret = curl_easy_perform(hnd);

var client = new RestClient("https://metrics-api.nanostream.cloud/authenticate");
var request = new RestRequest(Method.POST);
request.AddHeader("content-type", "application/json");
request.AddParameter("application/json", "{\"email\":\"foo@bar.foo\",\"password\":\"secretFooBar\"}", ParameterType.RequestBody);
IRestResponse response = client.Execute(request);

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://metrics-api.nanostream.cloud/authenticate"),
    Content = new StringContent("{\"email\":\"foo@bar.foo\",\"password\":\"secretFooBar\"}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

